package dk.sdu.cbse.gamelab;import javafx.animation.AnimationTimer;import javafx.application.Application;import javafx.scene.*;import javafx.scene.canvas.*;import javafx.scene.input.KeyCode;import javafx.scene.paint.Color;import javafx.stage.Stage;import java.util.*;public class GameLabApp extends Application{private final GameData d=new GameData();private final List<IGamePluginService> plugins=List.of(new PlayerComponent(),new EnemyComponent(),new AsteroidComponent(),new WeaponComponent());private final List<IEntityProcessingService> processors=List.of(new PlayerComponent(),new EnemyComponent(),new AsteroidComponent(),new WeaponComponent());private final IPostEntityProcessingService collision=new CollisionComponent();public void start(Stage stage){Canvas c=new Canvas(800,600);Scene s=new Scene(new Group(c));s.setOnKeyPressed(e->key(e.getCode(),true));s.setOnKeyReleased(e->key(e.getCode(),false));plugins.forEach(p->p.start(d));stage.setTitle("GameLab - JavaFX Asteroids");stage.setScene(s);stage.show();new AnimationTimer(){long last;public void handle(long n){double dt=last==0?0:Math.min((n-last)/1e9,.05);last=n;processors.forEach(p->p.process(d,dt));collision.process(d,dt);draw(c.getGraphicsContext2D());}}.start();}private void key(KeyCode k,boolean on){String x=switch(k){case LEFT->"LEFT";case RIGHT->"RIGHT";case UP->"UP";case SPACE->"FIRE";default->"";};if(!x.isEmpty()){if(on)d.keys.add(x);else d.keys.remove(x);}}private void draw(GraphicsContext g){g.setFill(Color.BLACK);g.fillRect(0,0,800,600);for(Entity e:d.entities){g.setStroke(switch(e.type){case"PLAYER"->Color.CYAN;case"ENEMY"->Color.RED;case"BULLET"->Color.YELLOW;default->Color.GRAY;});g.strokeOval(e.x-e.radius,e.y-e.radius,e.radius*2,e.radius*2);}}public static void main(String[] a){launch(a);}}